snippet_css:
:root{
  --bg: #111014;
  --fg: #E4D5B7;
  --muted: #C0AE8A;
  --surface: #1F2B24;
  --border: #3B2A1E;
  --accent: #C6A45A;
  --accent-fg: #14120E;
  --radius: 4px;
  --radius-sm: 3px;
  --shadow: 0 14px 34px rgba(0,0,0,.55);
  --btn-shadow: 0 0 0 1px rgba(198,164,90,.45),0 8px 22px rgba(0,0,0,.5);
  --art-bg: radial-gradient(circle at 50% 60%,#9E2A30 0 12%,#7E1F24 13% 15%,transparent 16%),linear-gradient(160deg,#1F2B24,#111014);
  --media-bg: linear-gradient(180deg,#1F2B24,#111014);
  --cta-bg: linear-gradient(180deg,#1F2B24,#111014);
  --input-bg: #16181A;
  --ok: #8FBF6A;
  --warn: #B4453F;
  --font-display: 'Cinzel Decorative','Noto Serif TC',serif;
  --font-body: 'EB Garamond','Noto Serif TC',serif;
  --font-mono: 'IBM Plex Mono',ui-monospace,monospace;
  --focus-ring: var(--accent);
}

